def get_user_input():
    """Get user input for two numbers and an operation."""
    while True:
        try:
            num1 = float(input("Enter first number: "))
            num2 = float(input("Enter second number: "))
            operation = input("Enter operation (+, -, *, /): ").upper()
            return num1, num2, operation
        except ValueError:
            print("Invalid input. Please enter numbers and a valid operation.")

def perform_operation(num1, num2, operation):
    """Perform the given operation on two numbers."""
    if operation == '+':
        result = num1 + num2
    elif operation == '-':
        result = num1 - num2
    elif operation == '*':
        result = num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        result = num1 / num2
    else:
        raise ValueError("Invalid operation. Choose from (+, -, *, /).")
    return result

def main():
    """Main function to get user input, perform operations, and display results."""
    num1, num2, operation = get_user_input()
    try:
        result = perform_operation(num1, num2, operation)
        print(f"Result: {result}")
    except ValueError as e:
        print(e)

if __name__ == "__main__":
    main()
```

This program defines three functions: `get_user_input()` to get user input, `perform_operation()` to perform the given operation, and `main()` to get user input, perform operations, and display results. The `main()` function calls the other two functions to handle user input and perform calculations.
